local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["0f070d33acda19c9"] = { "L'altare sembra chiamarti a sé come se fosse vivo.", "." },
  ["0f0cc408ac00426d"] = { "Garantisco la sicurezza di questa banca con il mio stesso sangue, ti basta?", "." },
  ["0f16000ad2459f4e"] = { "Non lasciarti imbrogliare dagli umani del Bazar, <ragazzo/ragazza>: con il tram che hanno costruito quegli gnomi, trasportare merci da ⟦Ironforge=Forgiardente⟧ è più facile di quanto pensi. Se provano ad aggiungere dazi d'importazione, digli che comprerai la tua roba da me.", "." },
  ["0f1a48b99218b384"] = { "Gli elementi ci parlano, {class}. Condividono conoscenze che dobbiamo apprendere, e segreti che devono essere custoditi.", "." },
  ["0f213498d00b872e"] = { "L'anziana Calca Nebbia ama guardare gli scontri nella Fossa Infausta, a Feralas.", "." },
  ["0f2a4ad777ab98ca"] = { "Per la barba di Bronzbeard... ehm, la sua barba! Di che stai parlando?", "." },
  ["0f329f02aa35b193"] = { "{name}, farò in modo che tutti i miei amici del Cartello sappiano che oggi mi hai salvato la vita. Tieni: dovrò viaggiare senza bagagli, quindi serviti pure dalla mia scorta di materiali da sartoria e conciatura! Grazie ancora, ci si vede!", "." },
  ["0f3325e721244fb3"] = { "Be', puoi trovare Theridan o Maldryn presso il pozzo lunare nel Parco. Dirigiti nella zona occidentale di ⟦Stormwind=Roccavento⟧, a nord del Quartiere dei Maghi, ma a ovest di Cathedral Square.", "." },
  ["0f4485ffaa3e828e"] = { "Sempre così pessimista. Le probabilità che succeda sono tra zero e nessuna.", "." },
  ["0f48dc893c7714c7"] = { "Ah sì? Allora sai quanto era debole e patetica la versione della magia troll degli alti elfi?\n\nGli alti elfi non riuscivano a capire perché un popolo con la loro affinità magica non potesse competere con i poteri del voodoo troll. Era un'idea inconcepibile per quei visi pallidi. Si rassegnarono a usare una versione imbastardita degli incantamenti troll. Credo li chiamassero «Arcanum».", "." },
  ["0f4df7c6a9d00d57"] = { "Bah! {name}, questo piede non si muove!", "." },
  ["0f54b27e2bce2bdd"] = { "Se cado nell'abisso, mi porterò dietro tutti voi mortali!", "." },
  ["0f54f777f3ca777f"] = { "Ehm... non ti conosco poi così bene, scusa. Voglio dire, con la mia licenza di rivendita autorizzata di Tecnostruzzi, posso vendere le mie cavalcature solo a chi è considerato amico degli gnomi. Se mai Gnomeregan ti considererà amichevole, sarò felice di mostrarti ciò che ho da offrire.", "." },
  ["0f5509087b9bacb9"] = { "È un onore rivederti, {name}.", "." },
  ["0f58121ff37c7e7b"] = { "Minaccia analizzata! Attivazione piano di combattimento beta! COCCODÈ!", "." },
  ["0f60b82c560a651a"] = { "Draghi che controllano orchi!? QUAAAK!", "." },
  ["0f6226eb4f10a6f1"] = { "Voglio imparare la mia specializzazione in Conciatura.", "." },
  ["0f675b3bf6f00be3"] = { "Ehm, sai già tutto quello che potrei insegnarti. Forse è ora che tu parli con qualcun altro. Prova con l'elfa della notte Ainethil, nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus. Ha un vero talento!", "." },
  ["0f6a3ecf99a08445"] = { "Throm-Ka, {class}. Oggi sono di pessimo umore, quindi, a meno che tu non possa aiutarmi, preferirei non avere compagnia.", "." },
  ["0f6d5a145bec864b"] = { "Dov'è l'anziano Cuornero?", "." },
  ["0f70c08a874115f2"] = { "Per i conciatori, la scelta migliore è ⟦Ironforge=Forgiardente⟧. Se la memoria non m'inganna, c'è una bottega vicino alla ⟦Great Forge=Grande Forgia⟧ che dovrebbe fare al caso tuo.", "." },
  ["0f72ea143b2c01e6"] = { "Credi che abbia perso il senno, mortale? Perché solo uno sciocco resterebbe qui a combattere contro di te e tutti i tuoi alleati. Forse un'altra volta... Se mai troverai il coraggio di sostenere le tue spacconate.", "." },
  ["0f7c5f1d8219b0ec"] = { "%s irrompe nell'incubatoio non appena applichi l'esca al cristallo!", "." },
  ["0f7c71d6d556a7e1"] = { "Staghelm piagnucolerà e implorerà per la sua vita, proprio come fece quel moccioso di suo figlio! Mille anni di ingiustizia finiranno oggi!", "." },
  ["0f7cb30fed405453"] = { "Addio, e che la Luce sia sempre con te.", "." },
  ["0f93f67c80f380ce"] = { "Il Pilastro Occidentale accetta cristalli rossi, verdi e blu.\n\nIl Pilastro si concentra sull'energia che si può creare usando i cristalli rossi come fonte principale di potere. Ci sono due effetti possibili: uno aumenta la tua protezione dai danni, l'altro indebolisce le difese di un nemico.\n\nDifesa del Cristallo richiede cristalli rossi e verdi. Ti fornirà un aumento dell'Armatura.\n\nResa del Cristallo richiede cristalli blu e rossi. Può ridurre l'Armatura di un bersaglio specifico.", "." },
  ["0f9a5148bda05fac"] = { "Pochi da queste parti maneggiano la lama come Lyria Du Lac. Cercala dietro la fucina e vedi se è dell'umore giusto per insegnarti qualcosa di nuovo.", "." },
  ["0f9b1075c5784262"] = { "<Benvenuto/Benvenuta> alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧, fondata dal mio caro vecchio papà, Arkilus Thunderbrew. Mando avanti io il posto da quando mio fratello maggiore, Grimbooze, è sparito in una nebbia alcolica qualche raccolto fa.", "." },
  ["0fa60d446d622612"] = { "Vuoi aiutare i Reietti nella loro lotta contro gli umani nel ⟦Arathi Basin=Bacino d'Arathi⟧? Allora va' nella Hall of the Brave e parla con ⟦Deze Snowbane=Deze Freddaneve⟧.", "." },
  ["0fae1f40f585d017"] = { "Mortali sconsiderati! Nessuno può sfidare i Figli della Fiamma Vivente!", "." },
  ["0fb1cf1d4a2edda3"] = { "La banca", "." },
  ["0fc1fe54c2e3c342"] = { "Fate un banchetto di {name}, mie bellezze!", "." },
  ["0fcef183ed2ad734"] = { "Oh, giusto! Da questa parte, ora...", "." },
  ["0fd4beca03fce3fc"] = { "Uthrok fa bel tiro", "." },
  ["0fd9e3216609181c"] = { "Chi sei? Cosa vuoi da me?", "." },
  ["0fe56123ae693651"] = { "L'equilibrio della natura è delicato, e basta poco per spezzarlo. Hai il coraggio di rimettere le cose a posto?", "." },
  ["0fe7dd45e6ee46b1"] = { "%s condivide i suoi poteri con i suoi fratelli.", "." },
  ["0fe952540ba4538b"] = { "Non arrendetevi! Combattete fino alla morte!", "." },
  ["0fead62c4b589ba9"] = { "Evviva il nuovo re!", "." },
  ["0feb9f8ffed7f112"] = { "Nulla libera lo spirito come librarsi nel cielo. C'è un posto così nel nostro grande centro tribale, ⟦Thunder Bluff=Picco del Tuono⟧. La strada che esce a nord dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ ti guiderà fin lì. Quando avrai preso l'ascensore fino in cima, parla con uno dei Guardiani del Picco, che potrà darti altre indicazioni.", "." },
  ["0ff2f67044747f10"] = { "Renataki, delle ⟦Thousand Blades=Mille Lame⟧.\n\nIl dolore è la sua linfa vitale. La paura, la sua alleata. Che possa un giorno tornare e portare con sé un gioioso spargimento di sangue.\n\nRenataki ora dimora ai confini della follia.", "." },
  ["0ffa3014f77c05c6"] = { "%s colpisce!", "." },
})
